from gurobipy import Model, GRB, quicksum
cabinet_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
cabinets = []
cabinet_capacities = {}
for rec in cabinet_records:
    cab_id = rec['values']['CabinetID']
    cap = float(rec['values']['Capacity'])
    cabinets.append(cab_id)
    cabinet_capacities[cab_id] = cap
products = []
product_values = {}
product_weights = {}
for rec in product_records:
    pname = rec['values']['ProductName']
    val = float(rec['values']['Value'])
    wt = float(rec['values']['Weight'])
    products.append(pname)
    product_values[pname] = val
    product_weights[pname] = wt
if len(cabinets) == 0 or len(products) == 0:
    raise RuntimeError('Missing cabinets or products in LEGACY_RECORDS')
for cab in cabinets:
    if cab not in cabinet_capacities:
        raise RuntimeError(f'Missing capacity for cabinet {cab}')
for prod in products:
    if prod not in product_values or prod not in product_weights:
        raise RuntimeError(f'Missing value/weight for product {prod}')

def build_model():
    m = Model()
    x_vars = m.addVars(cabinets, products, vtype=GRB.INTEGER, lb=0, name='')
    m.setObjective(quicksum((product_values[j] * x_vars[i, j] for i in cabinets for j in products)), GRB.MAXIMIZE)
    for i in cabinets:
        m.addConstr(quicksum((product_weights[j] * x_vars[i, j] for j in products)) <= cabinet_capacities[i], name=f'cap_{i}')
    m.Params.MIPGap = 0.0001
    return m
m = build_model()
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName} {v.X}')
else:
    print(f'Solver status: {m.Status}')
